class Solution {
public:
    vector<int> getSumAbsoluteDifferences(vector<int>& nums) {
        int n = nums.size();
        long long total = 0;
        for (int x : nums) total += x;

        vector<int> result(n);
        long long leftSum = 0;
        for (int i = 0; i < n; i++) {
            long long rightSum = total - leftSum - nums[i];
            long long res = (long long)nums[i] * i - leftSum
                          + rightSum - (long long)nums[i] * (n - i - 1);
            result[i] = (int)res;
            leftSum += nums[i];
        }
        return result;
    }
};
